mapper.select:
SELECT * FROM ( SELECT ct.transaction_id AS transactionid, ct.transaction_date AS transactionDate, ct.transaction_num AS transactionNum, (select fc.currency_name from fnd_currency fc where fc.currency_code = ct.currency_code) currencyCode, hbm.bp_name AS bpName, ct.description AS description, ct.bank_slip_num bankSlipNum, ct.business_type AS business_type, ct.transaction_amount AS transactionAmount, nvl(ct.write_off_amount,0) AS writeOffAmount, nvl(ct.transaction_amount,0)-nvl(ct.write_off_amount,0) AS unWriteOffAmount, cba.bank_account_name AS bankAccountName, cba.bank_account_num AS bankAccountNum, cb.bank_name AS bankName, ct.bp_bank_account_num AS bpBankAccountNum, ct.bp_bank_account_name AS bpBankAccountName, ct.bp_bank_name AS bpBankName, ct.write_off_flag AS writeOffFlag, ct.import_flag, ct.creation_date, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'CSH.PAYMENT_METHOD' and scvb.value = ct.payment_method) paymentMethod, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'CON.WRITE_OFF_FLAG' and scvb.value = ct.write_off_flag) as writeOffFlagDesc, CASE WHEN ( SELECT COUNT(1) FROM CSH_WRITE_OFF_MATCH COM WHERE COM.CSH_TRANSACTION_ID=ct.TRANSACTION_ID)=0 THEN 'NOT' WHEN ( SELECT COUNT(1) FROM CSH_WRITE_OFF_MATCH COM WHERE COM.WRITE_FLAG='N' AND COM.CSH_TRANSACTION_ID=ct.TRANSACTION_ID)>0 THEN 'NEW' WHEN ( SELECT COUNT(1) FROM CSH_WRITE_OFF_MATCH COM WHERE COM.WRITE_FLAG='R' AND COM.CSH_TRANSACTION_ID=ct.TRANSACTION_ID)>0 THEN 'REJECT' ELSE 'CHECK' END matchStatus, (select count(1) from csh_write_off o where o.csh_transaction_id=ct.transaction_id) writeOffCount, ct.company_id, ct.posted_flag, (nvl(ct.transaction_amount, 0) - nvl((SELECT SUM(nvl(wo.csh_write_off_amount, 0)) FROM csh_write_off wo WHERE wo.csh_transaction_id = ct.transaction_id AND wo.reversed_flag = 'N' AND (wo.write_off_type != 'REFUND' or wo.write_off_type = 'REFUND')), 0)) can_return_amount FROM csh_transaction ct, hls_bp_master hbm, csh_bank_account cba, csh_bank cb
cba.bank_account_id = ct.bank_account_id AND cba.bank_id = cb.bank_id AND hbm.bp_id(+) = ct.bp_id AND ct.reversed_flag = 'N' AND (ct.transaction_type = 'RECEIPT' OR ct.transaction_type = 'ADVANCE_RECEIPT')
) tran where 1=1
and tran.writeOffFlag = #{writeOffStatus}
and tran.matchStatus = #{matchStatus}
and trunc(tran.transactionDate) >= #{transactionDateFrom}
and trunc(tran.transactionDate) <= #{transactionDateTo}
AND tran.bpname like #{bpName}
AND (tran.bankName like #{bankInf} or tran.bankaccountnum like #{bankInf} or tran.bankaccountname like #{bankInf})
and ((#{roleId} = '10037' and tran.matchStatus in ('REJECT','NOT')) OR (#{roleId} = '10013' AND tran.matchStatus in ('NEW','CHECK')) OR (#{roleId} = #{roleId} and #{roleId} not in ('10013','10037') ))
ORDER BY
tran.transactionid DESC

(SELECT cwo.write_off_id, cwo.subsequent_csh_trx_id as transaction_id, cwo.csh_write_off_amount, cwo.write_off_date, cwo.write_off_type, cwo.reversed_flag, cwo.import_flag, scv.meaning, fc.approval_number, fqc.times, hci.description cf_item_desc, case when fqc.cf_item=54 then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.principal_repayment_party='Y' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) when fqc.cf_item=51 then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.repay_guarantee_party='Y' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) else ( case fp.fund_restream_method when 'DIRECT' then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.bp_role_type='SELLER' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) else ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.bp_role_type='BUYER' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) end) end bp_name FROM csh_write_off cwo JOIN csh_transaction ct ON ct.transaction_id = cwo.csh_transaction_id JOIN
scv ON scv.code = 'CSH.WRITE_OFF_TYPE' AND scv.code_value = cwo.write_off_type LEFT JOIN fct_quotation_cashflow fqc ON fqc.quotation_cashflow_id=cwo.cashflow_id LEFT JOIN fct_contract fc ON fc.contract_id=fqc.contract_id LEFT JOIN fct_project fp ON fp.project_id=fc.project_id LEFT JOIN hls_cashflow_item hci ON hci.cf_item=fqc.cf_item WHERE (cwo.write_off_doc_category='FCT_CONTRACT' or cwo.write_off_doc_category is null)
AND ct.transaction_id = #{transaction_id}
) UNION (SELECT cwo.write_off_id, cwo.subsequent_csh_trx_id as transaction_id, cwo.csh_write_off_amount, cwo.write_off_date, cwo.write_off_type, cwo.reversed_flag, cwo.import_flag, scv.meaning, pp.approval_number, ccc.times, hci.description cf_item_desc, hbm.bp_name FROM csh_write_off cwo JOIN csh_transaction ct ON ct.transaction_id = cwo.csh_transaction_id JOIN
scv ON scv.code = 'CSH.WRITE_OFF_TYPE' AND scv.code_value = cwo.write_off_type LEFT JOIN con_contract_cashflow ccc ON ccc.cashflow_id=cwo.cashflow_id LEFT JOIN con_contract cc ON cc.contract_id=ccc.contract_id LEFT JOIN prj_project pp ON pp.project_id=cc.project_id LEFT JOIN hls_cashflow_item hci ON hci.cf_item=ccc.cf_item LEFT JOIN hls_bp_master hbm ON cc.tenant_id=hbm.bp_id WHERE cwo.write_off_doc_category='CON_CONTRACT'
AND ct.transaction_id = #{transaction_id}
)

mapper.update:
update csh_transaction ct
set ct.reversed_trx_id = #{reversedTrxId,jdbcType=VARCHAR}
where ct.transaction_id = #{transactionId,jdbcType=BIGINT}

mapper.select:
SELECT t1.*, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'SYS.YES_NO' AND scb.CODE_ID = scv.CODE_ID AND scv.value = t1.refund_flag) refund_flag_n, (select i.description from hls_cashflow_item i where i.cf_item = t1.cf_item)cf_item_desc, (select cc.due_amount from con_contract_cashflow cc where cc.cashflow_id = t1.cashflow_id) due_amount, (select cc.due_date from con_contract_cashflow cc where cc.cashflow_id = t1.cashflow_id) due_date FROM (SELECT t.*, (select o.cf_item from csh_write_off o where o.write_off_id = t.source_doc_line_id)cf_item, (select o.cashflow_id from csh_write_off o where o.write_off_id = t.source_doc_line_id)cashflow_id, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'CSH301_TRANSACTION_TYPE' AND v.code_value = t.transaction_type) transaction_type_n, (SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = t.CURRENCY_CODE) AS currency_n, (SELECT cba.BANK_ACCOUNT_NAME FROM csh_bank_account cba WHERE cba.BANK_ACCOUNT_ID = t.bank_account_id) AS BANK_ACCOUNT_NAME, (SELECT cba.BANK_ACCOUNT_NUM FROM csh_bank_account cba WHERE cba.BANK_ACCOUNT_ID = t.bank_account_id) AS BANK_ACCOUNT_NUM, (SELECT bp.bp_code FROM hls_bp_master bp WHERE bp.BP_ID = t.BP_ID) AS bp_code, (SELECT bp.bp_name FROM hls_bp_master bp WHERE bp.BP_ID = t.BP_ID) AS bp_name,
nvl((SELECT SUM(nvl(wo.csh_write_off_amount, 0)) FROM csh_write_off wo WHERE wo.csh_transaction_id = t.transaction_id AND wo.reversed_flag = 'N' AND wo.write_off_type = 'REFUND'), 0) return_write_off_amount,
nvl((SELECT SUM(nvl(wo.csh_write_off_amount, 0)) FROM csh_write_off wo WHERE wo.csh_transaction_id = t.transaction_id AND wo.reversed_flag = 'N' AND wo.write_off_type != 'REFUND'), 0) sum_write_off_amount,
(nvl(t.transaction_amount, 0) - nvl(t.write_off_amount, 0) - nvl(( SELECT nvl(SUM(c.due_amount),0)-ifnull (SUM(c.received_amount),0) FROM fct_quotation_cashflow c WHERE c.cf_item=14 AND c.contract_id=t.contract_id),0)) can_return_amount,
nvl((select sum(d.deduction_amount) from csh_deposit_deduction d, csh_deposit_deduction_hd hd where hd.transaction_id=t.transaction_id and d.deposit_deduction_hd_id=hd.deposit_deduction_hd_id and hd.deposit_status in('NEW','APPROVING','REJECTED','APPROVED_RETURN')),0) + nvl((select sum(dr.refund_amount) from csh_deposit_refund dr where dr.transaction_id=t.transaction_id and dr.refund_status!='APPROVED'),0)pre_occupy_amount,
(SELECT max(hbmt.bp_name) FROM hls_bp_master hbmt,con_contract_bp ccb where hbmt.bp_id = ccb.bp_id and ccb.contract_id=t.contract_id and ccb.bp_category='WARRANTOR' ) as guarantor_bp_name,
(SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID AND scv.value = t.payment_method) payment_method_n,
(SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.POST_SELECT' AND scb.CODE_ID = scv.CODE_ID AND scv.value = t.posted_flag) posted_flag_n,
(CASE WHEN (SELECT COUNT(1) FROM csh_transaction ct WHERE ct.source_doc_id = t.transaction_id AND ct.transaction_type = 'REFUND' AND ct.reversed_flag = 'N') = 0 THEN 'N' ELSE 'Y' END) refund_flag, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'HLS_REVERSED_FLAG' AND scb.CODE_ID = scv.CODE_ID AND scv.value = t.reversed_flag) reversed_flag_n,
(SELECT c.contract_id FROM csh_write_off o, con_contract c WHERE o.write_off_id = t.source_doc_line_id AND t.source_doc_category = 'CSH_WRITE_OFF' AND o.write_off_type = 'RECEIPT_CREDIT' and o.cf_item=51 AND c.contract_id = o.contract_id AND o.reversed_flag = 'N') deposit_contract_id,
(SELECT c.contract_name from con_contract c where c.contract_id = t.contract_id) deposit_contract_name, (SELECT c.contract_number from con_contract c where c.contract_id = t.contract_id) deposit_contract_number,
(SELECT c.contract_status FROM con_contract c WHERE c.contract_id = t.contract_id) contract_status,
(SELECT v.meaning FROM con_contract c, sys_code_value_b_v v WHERE c.contract_id = t.contract_id and v.CODE = 'CON.CONTRACT_STATUS' and v.code_value = c.contract_status) contract_status_desc,
nvl((SELECT c.finance_amount from con_contract c where c.contract_id = t.contract_id),0) finance_amount,
(SELECT cc.contract_number FROM csh_payment_req_hd hd, csh_payment_req_ln ln, con_contract cc WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id AND ln.payment_req_id = hd.payment_req_id AND ln.payment_req_ln_id = (SELECT MAX(ll.payment_req_ln_id) FROM csh_payment_req_ln ll WHERE ll.payment_req_id = hd.payment_req_id) AND cc.contract_id = ln.source_doc_id) contract_number,
(SELECT cc.contract_name FROM csh_payment_req_hd hd, csh_payment_req_ln ln, con_contract cc WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id AND ln.payment_req_id = hd.payment_req_id AND ln.payment_req_ln_id = (SELECT MAX(ll.payment_req_ln_id) FROM csh_payment_req_ln ll WHERE ll.payment_req_id = hd.payment_req_id) AND cc.contract_id = ln.source_doc_id) contract_name,
(SELECT hd.payment_req_number FROM csh_payment_req_hd hd WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id) payment_req_number,
(SELECT hd.apply_pay_date FROM csh_payment_req_hd hd WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id) apply_pay_date,
(SELECT hd.payment_req_date FROM csh_payment_req_hd hd WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id) payment_req_date,
(SELECT bp.bp_code FROM csh_payment_req_hd hd, csh_payment_req_ln ln, hls_bp_master bp WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id AND ln.payment_req_id = hd.payment_req_id AND ln.payment_req_ln_id = (SELECT MAX(ll.payment_req_ln_id) FROM csh_payment_req_ln ll WHERE ll.payment_req_id = hd.payment_req_id) AND bp.bp_id = ln.bp_id) payment_bp_code, (SELECT bp.bp_name FROM csh_payment_req_hd hd, csh_payment_req_ln ln, hls_bp_master bp WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id AND ln.payment_req_id = hd.payment_req_id AND ln.payment_req_ln_id = (SELECT MAX(ll.payment_req_ln_id) FROM csh_payment_req_ln ll WHERE ll.payment_req_id = hd.payment_req_id) AND bp.bp_id = ln.bp_id) payment_bp_name,
(SELECT ln.bp_bank_account_num FROM csh_payment_req_hd hd, csh_payment_req_ln ln WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id AND ln.payment_req_id = hd.payment_req_id AND ln.payment_req_ln_id = (SELECT MAX(ll.payment_req_ln_id) FROM csh_payment_req_ln ll WHERE ll.payment_req_id = hd.payment_req_id)) payment_bp_bank_account_num, (SELECT ln.bp_bank_account_name FROM csh_payment_req_hd hd, csh_payment_req_ln ln WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id AND ln.payment_req_id = hd.payment_req_id AND ln.payment_req_ln_id = (SELECT MAX(ll.payment_req_ln_id) FROM csh_payment_req_ln ll WHERE ll.payment_req_id = hd.payment_req_id)) payment_bp_bank_account_name, (SELECT ln.bp_bank_branch_name FROM csh_payment_req_hd hd, csh_payment_req_ln ln WHERE t.source_doc_category = 'CSH_PAYMENT_REQ' AND t.source_doc_id = hd.payment_req_id AND ln.payment_req_id = hd.payment_req_id AND ln.payment_req_ln_id = (SELECT MAX(ll.payment_req_ln_id) FROM csh_payment_req_ln ll WHERE ll.payment_req_id = hd.payment_req_id)) payment_bp_bank_branch_name, (select m.write_off_date from csh_write_off_match m where m.csh_transaction_id = t.transaction_id and rownum=1)as write_off_date, (select r.refund_number from csh_transaction_refund r where r.transaction_id = t.source_doc_id and t.source_doc_category = 'CSH_WRITE_OFF' and t.transaction_type = 'REFUND' and rownum=1)refund_number, (select r.refund_id from csh_transaction_refund r where r.transaction_id = t.source_doc_id and t.source_doc_category = 'CSH_WRITE_OFF' and t.transaction_type = 'REFUND' and rownum=1)refund_id, t.transaction_date as period_number FROM csh_transaction t) t1
1=1
AND t1.transaction_date >= #{transactionDateFrom}
AND t1.transaction_date <= #{transactionDateTo}
AND t1.transaction_amount >= #{transactionAmountFrom}
AND t1.transaction_amount <= #{transactionAmountTo}
AND t1.bank_account_num concat('%',concat(#{bankAccountNum},'%') )
AND t1.bp_name like concat('%',concat(#{bpName},'%') )
AND t1.transaction_id = #{transactionId}
AND ('Y'=#{receiptFlag} and t1.transaction_type in ('ADVANCE_RECEIPT','RECEIPT'))
AND ('Y'=#{paymentFlag} and t1.transaction_type in ('PREPAYMENT','PAYMENT','DEDUCTION'))
AND t1.transaction_type=#{transactionType}
AND t1.business_type=#{businessType}
AND t1.bp_id=#{bpId}
AND t1.company_id=#{companyId}
AND t1.source_doc_category=#{sourceDocCategory}
AND t1.source_doc_id=#{sourceDocId}
AND t1.payment_method=#{paymentMethod}
AND t1.posted_flag=#{postedFlag}
AND t1.refund_flag=#{refundFlag}
AND t1.reversed_flag=#{reversedFlag}
AND t1.payment_req_number >= #{paymentReqNumberFrom}
AND t1.payment_req_number <= #{paymentReqNumberTo}
AND t1.payment_req_date >= #{paymentReqDateFrom}
AND t1.payment_req_date <= #{paymentReqDateTo}
AND t1.contract_number like concat('%',concat(#{contractNumber},'%') )
AND t1.payment_bp_name like concat('%',concat(#{paymentBpName},'%') )
AND t1.transaction_num like concat('%',concat(#{transactionNum},'%') )
AND t1.deposit_contract_number >= #{depositContractNumberFrom}
AND t1.deposit_contract_number <= #{depositContractNumberTo}
AND t1.deposit_contract_name like concat('%',concat(#{depositContractName},'%') )
AND t1.deposit_contract_id =#{depositContractId}
AND t1.contract_status=#{contractStatus}
order by t1.transaction_num desc

SELECT ct.*, (SELECT scv.DESCRIPTION FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = ct.payment_method) gathering_method, (select bm.bp_code from hls_bp_master bm where bm.bp_id = ct.bp_id) bp_code, (select bm.bp_name from hls_bp_master bm where bm.bp_id = ct.bp_id) bp_name, (select cba.bank_account_name from csh_bank_account cba where cba.bank_account_id = ct.bank_account_id) bank_account_name,
(select cba.currency from csh_bank_account cba where cba.bank_account_id = ct.bank_account_id) currency_code,
(select cba.bank_account_num from csh_bank_account cba where cba.bank_account_id = ct.bank_account_id) bank_account_num, nvl((select sum(wo.csh_write_off_amount) from csh_write_off wo where wo.csh_transaction_id = ct.transaction_id and wo.write_off_type = 'REFUND'), 0) return_write_off_amount, nvl((select sum(wo.csh_write_off_amount) from csh_write_off wo where wo.csh_transaction_id = ct.transaction_id and wo.write_off_type != 'REFUND'), 0) sum_write_off_amount, (nvl(ct.transaction_amount, 0) - nvl(ct.write_off_amount, 0)) can_return_amount FROM csh_transaction ct where ct.transaction_id = #{transactionId}

select ttt1.* from ( select t1.*, nvl(t1.transaction_amount-nvl(t1.refund_amount,0)-nvl(t1.write_off_amount,0)-nvl(t1.refunding_amount,0),0) un_write_off_amount, ( CASE WHEN t1.ctr_refund_flag = 0 THEN 'N' ELSE 'Y' END ) AS refund_flag, ( CASE WHEN t1.ctr_refund_flag = 0 THEN '否' ELSE '是' END ) AS refund_flag_n from ( select tran.*, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'HLS_WFL_STATUS' AND v.code_value = tran.refund_status) refund_status_desc, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CSH301_TRANSACTION_TYPE' AND v.code_value = tran.transaction_type) transaction_type_n, /* tran.un_write_off_amount_pre - nvl((SELECT SUM(tt.transaction_amount) FROM csh_transaction tt WHERE tt.source_doc_id = tran.advance_csh_trx_id AND tt.transaction_type = 'REFUND'), 0) AS un_write_off_amount,*/ /* (SELECT case when COUNT(1) = 0 then 'N' else 'Y' end FROM csh_transaction tt WHERE tt.source_doc_id = tran.advance_csh_trx_id AND tt.transaction_type = 'REFUND') AS refund_flag, (SELECT case when COUNT(1) = 0 then '否' else '是' end FROM csh_transaction tt WHERE tt.source_doc_id = tran.advance_csh_trx_id AND tt.transaction_type = 'REFUND') AS refund_flag_n,*/ /* ( CASE WHEN tran.ctr_refund_flag = 0 THEN 'N' ELSE 'Y' END ) AS refund_flag, ( CASE WHEN tran.ctr_refund_flag = 0 THEN '否' ELSE '是' END ) AS refund_flag_n,*/ /* nvl((SELECT SUM(tt.transaction_amount) FROM csh_transaction tt WHERE tt.source_doc_id = tran.advance_csh_trx_id AND tt.transaction_type = 'REFUND'), 0) AS refund_amount,*/ ( SELECT sum(ctr.REFUND_AMOUNT) FROM csh_transaction_refund ctr WHERE ctr.refund_status = 'APPROVED' AND ctr.TRANSACTION_ID = tran.TRANSACTION_ID ) refund_amount, ( SELECT sum(ctr.REFUND_AMOUNT) FROM csh_transaction_refund ctr WHERE ctr.refund_status = 'APPROVING' AND ctr.TRANSACTION_ID = tran.TRANSACTION_ID ) refunding_amount, /* (tran.transaction_amount - tran.write_off_due_amount - tran.advance_write_off_amount) un_write_off_due_amount*/ (tran.transaction_amount - tran.write_off_due_amount) un_write_off_due_amount from (SELECT t.*, (SELECT f.refund_status FROM csh_transaction_refund f WHERE f.transaction_id = t.transaction_id AND f.refund_id =( SELECT max(csr.REFUND_ID ) FROM csh_transaction_refund csr WHERE
csr.TRANSACTION_ID=t.TRANSACTION_ID)) refund_status, (case when t.reversed_flag = 'N' then '否' else '是' end ) reversed_flag_n,
