e = 'RECEIPT_ADVANCE_RECEIPT' AND o.reversed_flag = 'N' and rownum=1) as advance_csh_trx_id, ( SELECT count(*) FROM csh_transaction_refund ctr WHERE ctr.refund_status = 'APPROVED' AND ctr.TRANSACTION_ID = t.TRANSACTION_ID ) ctr_refund_flag, (select c.contract_number from con_contract c where c.contract_id = t.contract_id) contract_number, (select c.contract_name from con_contract c where c.contract_id = t.contract_id) contract_name, nvl(t.write_off_amount, 0) write_off_due_amount, nvl((select sum(ctr.REFUND_AMOUNT) from csh_transaction_refund ctr where ctr.TRANSACTION_ID=t.TRANSACTION_ID and ctr.REFUND_STATUS in ('APPROVING','APPROVED') and ctr.PAYMENT_REFUND_STATUS !='PAID'),0) frozen_amount
