er_status = 'APPROVED' and cc.contract_id = t.contract_id and cprh.recheck = su.user_id) recheck, CASE WHEN ccc.bp_id IS NULL THEN ( SELECT hbm.bp_name FROM prj_project_bp ppb, hls_bp_master hbm,con_contract cc WHERE ppb.project_id = cc.project_id and t.contract_id = cc.contract_id AND ppb.bp_type = 'TENANT' AND ppb.bp_id = hbm.bp_id and rownum=1) ELSE ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = ccc.bp_id ) END AS bp_id_n, 0 as refund_id
