(SELECT cwo.csh_write_off_amount FROM csh_write_off cwo where cwo.write_off_id = t.source_doc_line_id) write_off_amount_detail,
(SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'CSH301_TRANSACTION_TYPE' AND scv.value = t.transaction_type) AS business_type_n, (SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'CHS.CURRENCY_TYPE' AND scv.value = t.currency_code) AS currency_code_n, (case when t.reversed_flag = 'N' then '否' else '是' end) AS reversed_flag_n, (SELECT case COUNT(1) = 0 then 'N' else 'Y' end FROM csh_transaction tt WHERE tt.source_doc_id = t.transaction_id AND tt.transaction_type = 'REFUND') AS refund_flag, (SELECT case when COUNT(1) = 0 then '未退款' else '已退款' end FROM csh_transaction tt WHERE tt.source_doc_id = t.transaction_id AND tt.transaction_type = 'REFUND') AS refund_flag_n, nvl((SELECT SUM(tt.transaction_amount) FROM csh_transaction tt WHERE tt.source_doc_id = t.transaction_id AND tt.transaction_type = 'REFUND'),0) AS refund_amount, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'WRITE_OFF_FLAG' AND v.code_value = t.write_off_flag) AS write_off_flag_desc, CASE WHEN (SELECT COUNT(1) FROM csh_write_off_match com WHERE com.csh_transaction_id = t.transaction_id) = 0 THEN 'NOT' WHEN (SELECT COUNT(1) FROM csh_write_off_match com WHERE com.write_flag = 'N' AND com.csh_transaction_id = t.transaction_id) > 0 THEN 'NEW' WHEN (SELECT COUNT(1) FROM csh_write_off_match com WHERE com.write_flag = 'R' AND com.csh_transaction_id = t.transaction_id) > 0 THEN 'REJECT' ELSE 'CHECK' END AS match_status, hbm.bp_name, nvl(t.transaction_amount, 0) - nvl(t.write_off_amount, 0) AS un_write_off_amount, nvl(t.transaction_amount, 0) - nvl((SELECT SUM(nvl(wo.csh_write_off_amount, 0)) FROM csh_write_off wo WHERE wo.csh_transaction_id = t.transaction_id AND wo.reversed_flag = 'N' AND (wo.write_off_type != 'REFUND' OR wo.write_off_type = 'REFUND')), 0) AS can_return_amount, (SELECT cprh.payment_req_id FROM con_contract cc, hls_funding_plan hfp, prj_project pp, csh_payment_req_hd cprh WHERE cc.contract_id = hfp.contract_id AND cc.project_id = pp.project_id AND hfp.funding_plan_id = cprh.funding_plan_id AND cprh.transfer_status = 'APPROVED' AND cc.contract_id = t.contract_id) AS payment_req_id, (SELECT cprh.funding_plan_id FROM con_contract cc, hls_funding_plan hfp, prj_project pp, csh_payment_req_hd cprh WHERE cc.contract_id = hfp.contract_id AND cc.project_id = pp.project_id AND hfp.funding_plan_id = cprh.funding_plan_id AND cprh.transfer_status = 'APPROVED' AND cc.contract_id = t.contract_id) AS funding_plan_id, (SELECT cc.contract_number FROM con_contract cc, prj_project pp WHERE cc.project_id = pp.project_id AND cc.contract_id = t.contract_id) AS payment_number, (SELECT pp.contract_name FROM con_contract cc, prj_project pp WHERE cc.contract_id = t.contract_id AND cc.project_id = pp.project_id) AS contract_name, (SELECT su.description FROM con_contract cc, prj_project pp, sys_user su WHERE cc.contract_id = t.contract_id AND cc.project_id = pp.project_id AND cc.host_project_manager = su.user_id) AS host_project_manager, (SELECT fou.unit_name FROM con_contract cc, prj_project pp, fnd_org_unit fou WHERE cc.contract_id = t.contract_id AND cc.project_id = pp.project_id AND cc.host_unit_id = fou.unit_id) AS host_unit_name, (SELECT su.description FROM con_contract cc, hls_funding_plan hfp, prj_project pp, csh_payment_req_hd cprh, sys_user su WHERE cc.contract_id = hfp.contract_id AND cc.project_id = pp.project_id AND hfp.funding_plan_id = cprh.funding_plan_id AND cprh.transfer_status = 'APPROVED' AND cc.contract_id = t.contract_id AND cprh.trial = su.user_id) AS trial, (SELECT su.description FROM con_contract cc, hls_funding_plan hfp, prj_project pp, csh_payment_req_hd cprh, sys_user su WHERE cc.contract_id = hfp.contract_id AND cc.project_id = pp.project_id AND hfp.funding_plan_id = cprh.funding_plan_id AND cprh.transfer_status = 'APPROVED' AND cc.contract_id = t.contract_id AND cprh.recheck = su.user_id) AS recheck, (SELECT hbm.bp_name FROM hls_bp_master hbm where hbm.bp_id = t.bp_id) as bp_id_n, (SELECT max(r.refund_id) FROM csh_transaction_refund r where r.transaction_id = t.source_doc_id ) as refund_id
FROM csh_transaction t LEFT JOIN hls_bp_master hbm ON hbm.bp_id = t.bp_id AND t.reversed_flag IN ('N', 'W')) tranrefund WHERE tranrefund.transaction_type in ('REFUND', 'DEPOSIT') ) tran
