(select b.PAYMENT_AMOUNT from csh_pay_req_ln_bank_account b where b.PAYMENT_REQ_LN_ID = ccc.cashflow_id) PAYMENT_AMOUNT, (select b.ACTUAL_PAYMENT_AMOUNT from csh_pay_req_ln_bank_account b where b.PAYMENT_REQ_LN_ID = ccc.cashflow_id) ACTUAL_PAYMENT_AMOUNT, (select hd.PAYMENT_APPROVED_STATUS from csh_payment_req_hd hd where hd.PAYMENT_REQ_ID = t.SOURCE_DOC_ID) PAYMENT_APPROVED_STATUS, (SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PAYMENT_APPROVED_STATUS' AND code_value = (select hd.PAYMENT_APPROVED_STATUS from csh_payment_req_hd hd where hd.PAYMENT_REQ_ID = t.SOURCE_DOC_ID)) PAYMENT_APPROVED_STATUS_N, t.source_doc_id, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'CSH301_TRANSACTION_TYPE' AND v.code_value = t.transaction_type) transaction_type_n, t.transaction_type
