select t1.* from (select ct.TRANSACTION_ID, ct.TRANSACTION_NUM, ct.TRANSACTION_TYPE, (select scvb.MEANING from sys_code_b scb left join sys_code_value_b scvb on scb.code = 'CSH301_TRANSACTION_TYPE' and scb.code_id = scvb.code_id where scvb.value = ct.TRANSACTION_TYPE) as TRANSACTION_TYPE_DESC, ct.TRANSACTION_AMOUNT, ct.TRANSACTION_DATE, ct.WRITE_OFF_AMOUNT, ct.bp_id as payment_bp_id, cc.CONTRACT_ID, cc.CONTRACT_NUMBER, cc.CONTRACT_NAME, (select bm.bp_name from hls_bp_master bm where bm.bp_id=ct.bp_id) bp_name,
nvl(ct.transaction_amount, 0) - ( SELECT nvl(SUM(nvl(cwo.csh_write_off_amount, 0)), 0) FROM csh_write_off cwo WHERE cwo.csh_transaction_id = ct.transaction_id AND cwo.reversed_flag = 'N' ) AS can_return_amount from csh_transaction ct LEFT JOIN con_contract cc ON ct.CONTRACT_ID = cc.contract_id where ct.WRITE_OFF_FLAG != 'FULL' and not EXISTS(select 1 from CSH_TRANSACTION_REFUND_LN l, csh_transaction_refund refund where l.REFUND_ID = refund.REFUND_ID and refund.TRANSACTION_ID = ct.TRANSACTION_ID and refund.REFUND_STATUS in ('NEW', 'APPROVING')) ) t1
