select t2.* from (SELECT t1.*, case when /*t1.after_deduct_amount <= 0 and t1.CONTRACT_STATUS = 'INCEPT' and */ t1.deposit_deduct_method = 'AUTO' then 'Y' else 'N' end as auto_deduct_flag, case when /*t1.after_deduct_amount <= 0 and t1.CONTRACT_STATUS = 'INCEPT' and */ t1.deposit_deduct_method = 'AUTO' then '是' else '否' end as auto_deduct_flag_n, (select md.BP_NAME from hls_bp_master md, con_contract ccd where ccd.contract_id = t1.deposit_contract_id and ccd.TENANT_id = md.BP_ID) as TENANT_id_n,
( SELECT q.quotation_number FROM prj_quotation q, con_contract_cashflow ccc, csh_write_off o WHERE q.quotation_id = ccc.generated_source_doc_id AND ccc.generated_source = 'PRJ_QUOTATION' AND ccc.cashflow_id = o.cashflow_id AND o.write_off_id = t1.source_doc_line_id ) contract_seq_num FROM ( SELECT t.*, ( select scvb.MEANING from SYS_CODE_B scb, SYS_CODE_VALUE_B scvb where scb.code = 'CON.CASHFLOW_WRITE_OFF_FLAG' AND scb.CODE_ID = scvb.CODE_ID and scvb.VALUE = t.WRITE_OFF_FLAG ) write_off_flag_n, ( select v.meaning from sys_code_value_b_v v where v.code = 'CSH301_TRANSACTION_TYPE' AND v.code_value = t.transaction_type ) transaction_type_n, (select fc.currency_name from fnd_currency fc where t.CURRENCY_CODE = fc.CURRENCY_CODE) AS currency_n, (select cba.BANK_ACCOUNT_NUM from CSH_BANK_ACCOUNT cba where t.BANK_ACCOUNT_ID = cba.BANK_ACCOUNT_ID) AS BANK_ACCOUNT_NUM, (select cba.BANK_ACCOUNT_NAME from CSH_BANK_ACCOUNT cba where t.BANK_ACCOUNT_ID = cba.BANK_ACCOUNT_ID) AS BANK_ACCOUNT_NAME, hbm.bp_code, hbm.bp_name, hbm.BP_TYPE, (SELECT hbt.description FROM hls_bp_type hbt WHERE hbt.bp_type = hbm.BP_TYPE) AS bp_type_n,
(nvl(t.transaction_amount, 0) - (Select nvl(Sum(nvl(line.REFUND_AMOUNT, 0)), 0) From CSH_TRANSACTION_REFUND_LN line, CSH_TRANSACTION_REFUND r Where line.refund_id = r.refund_id And r.refund_status In ('NEW', 'REJECTED') And line.SOURCE_TRANSACTION_ID = t.TRANSACTION_ID) - (Select nvl(Sum(cwo.csh_write_off_amount), 0) From csh_write_off cwo Where cwo.csh_transaction_id = t.transaction_id And cwo.reversed_flag = 'N') - nvl(t.BLOCK_AMOUNT, 0)) As can_return_amount,
(Select nvl(Sum(ll.REFUND_AMOUNT), 0) From CSH_TRANSACTION_REFUND_LN ll, CSH_TRANSACTION_REFUND r Where ll.refund_id = r.refund_id And r.refund_status = 'APPROVED' And ll.SOURCE_TRANSACTION_ID = t.TRANSACTION_ID ) as return_write_off_amount,
( SELECT nvl(SUM(nvl(wo.csh_write_off_amount, 0)),0) FROM csh_write_off wo WHERE wo.csh_transaction_id = t.transaction_id AND wo.reversed_flag = 'N' AND wo.write_off_type != 'REFUND' ) sum_write_off_amount, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.payment_method ) payment_method_n, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.POST_SELECT' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.posted_flag ) posted_flag_n, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'HLS_REVERSED_FLAG' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.reversed_flag ) reversed_flag_n, t.contract_id deposit_contract_id, (SELECT cc.contract_number FROM con_contract cc WHERE cc.contract_id = t.contract_id) deposit_contract_number, ( select cc.contract_number from csh_payment_req_hd hd, csh_payment_req_ln ln, con_contract cc where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id and ln.payment_req_id = hd.payment_req_id and cc.contract_id = ln.source_doc_id and ln.payment_req_ln_id = ( select max(ll.payment_req_ln_id) from csh_payment_req_ln ll where ll.payment_req_id = hd.payment_req_id ) ) contract_number, ( select hd.payment_req_number from csh_payment_req_hd hd where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id ) payment_req_number, ( select hd.apply_pay_date from csh_payment_req_hd hd where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id ) apply_pay_date, ( select hd.payment_req_date from csh_payment_req_hd hd where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id ) payment_req_date, ( select bp.bp_code from csh_payment_req_hd hd, csh_payment_req_ln ln, hls_bp_master bp where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id and ln.payment_req_id = hd.payment_req_id and ln.payment_req_ln_id = ( select max(ll.payment_req_ln_id) from csh_payment_req_ln ll where ll.payment_req_id = hd.payment_req_id ) and bp.bp_id = ln.bp_id ) payment_bp_code, ( select bp.bp_name from csh_payment_req_hd hd, csh_payment_req_ln ln, hls_bp_master bp where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id and ln.payment_req_id = hd.payment_req_id and ln.payment_req_ln_id = ( select max(ll.payment_req_ln_id) from csh_payment_req_ln ll where ll.payment_req_id = hd.payment_req_id ) and bp.bp_id = ln.bp_id ) payment_bp_name, ( select ln.bp_bank_account_num from csh_payment_req_hd hd, csh_payment_req_ln ln where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id and ln.payment_req_id = hd.payment_req_id and ln.payment_req_ln_id = ( select max(ll.payment_req_ln_id) from csh_payment_req_ln ll where ll.payment_req_id = hd.payment_req_id ) ) payment_bp_bank_account_num, ( select ln.bp_bank_account_name from csh_payment_req_hd hd, csh_payment_req_ln ln where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id and ln.payment_req_id = hd.payment_req_id and ln.payment_req_ln_id = ( select max(ll.payment_req_ln_id) from csh_payment_req_ln ll where ll.payment_req_id = hd.payment_req_id ) ) payment_bp_bank_account_name, ( select ln.bp_bank_branch_name from csh_payment_req_hd hd, csh_payment_req_ln ln where t.source_doc_category = 'CSH_PAYMENT_REQ' and t.source_doc_id = hd.payment_req_id and ln.payment_req_id = hd.payment_req_id and ln.payment_req_ln_id = ( select max(ll.payment_req_ln_id) from csh_payment_req_ln ll where ll.payment_req_id = hd.payment_req_id ) ) payment_bp_bank_branch_name, (select cc.manufacturer_id from con_contract cc where cc.contract_id = t.contract_id) manufacturer_id, nvl((select nvl(sum(cc.due_amount),0) - nvl(sum(cc.received_amount),0) from con_contract_cashflow cc where cc.contract_id = t.contract_id and cc.cf_item in (1,8,9,11,13)),0) as can_deduct_amount, (nvl((select nvl(sum(cc.due_amount),0) - nvl(sum(cc.received_amount),0) from con_contract_cashflow cc where cc.contract_id = t.contract_id and cc.cf_item in (1,8,9,11,13)),0) - nvl((select nvl(sum(ct2.transaction_amount), 0) - nvl(sum(ct2.WRITE_OFF_AMOUNT), 0) - nvl(sum(ct2.BLOCK_AMOUNT), 0) from csh_transaction ct2 where ct2.contract_id = t.contract_id),0)) as after_deduct_amount, (select cc.DEPOSIT_DEDUCT_METHOD from con_contract cc where cc.contract_id = t.contract_id) DEPOSIT_DEDUCT_METHOD, (select cc.lease_channel from con_contract cc where cc.contract_id = t.contract_id) lease_channel, (select cc.CONTRACT_STATUS from con_contract cc where cc.contract_id = t.contract_id) CONTRACT_STATUS FROM csh_transaction t left join HLS_BP_MASTER hbm on t.BP_ID = hbm.BP_ID ) t1
AND t1.transaction_date >= #{transactionDateFrom}
AND t1.transaction_date <= #{transactionDateTo}
