order by t1.transaction_num desc) t2
and t2.tenant_Id_N like #{tenantIdN}

SELECT t1.* FROM ( select cc.CONTRACT_ID, cc.contract_id as deposit_contract_id, cc.DATA_CLASS, cc.CONTRACT_NUMBER, cc.CONTRACT_NAME, cc.BUSINESS_TYPE, cc.DOCUMENT_TYPE, cc.DOCUMENT_CATEGORY, cc.PROJECT_ID, cc.COMPANY_ID, cc.LEASE_CHANNEL, cc.DIVISION, cc.TENANT_ID, cc.EMPLOYEE_ID, cc.UNIT_ID, cc.PRICE_LIST, cc.MANUFACTURER_ID, cc.FACTORY_ID, case when cc.contract_status = 'PENDING' then 'N' when cc.contract_status = 'CANCEL' then 'N' when cc.contract_status = 'TERMINATE' then 'N' when not exists (select 1 from csh_transaction t where t.contract_id = cc.contract_id AND t.transaction_type = 'DEPOSIT' AND t.reversed_flag = 'N' and t.transaction_amount > nvl(t.WRITE_OFF_AMOUNT, 0) + nvl(t.BLOCK_AMOUNT, 0)) then 'N' when not exists (select 1 from con_contract_cashflow cash where cash.contract_id = cc.contract_id AND cash.cf_status='RELEASE' AND CASH.due_amount-nvl(cash.RECEIVED_AMOUNT,0)>0) then 'N' else 'Y' end modify_flag, cc.deposit_deduct_method, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'DEPOSIT_DEDUCT_METHOD' AND v.code_value = cc.deposit_deduct_method) AS deposit_deduct_method_n, (SELECT hb.bp_name FROM hls_bp_master hb WHERE hb.bp_id = cc.factory_id) AS factory_id_n, (SELECT hb.bp_name FROM hls_bp_master hb WHERE hb.bp_id = cc.manufacturer_id) AS manufacturer_id_n, (select md.BP_NAME from hls_bp_master md where cc.tenant_id = md.BP_ID) as tenant_id_n, (select fe.name from fnd_employee fe where fe.employee_id = cc.employee_id) employee_id_n, nvl((select sum(t.transaction_amount) from csh_transaction t where t.contract_id = cc.contract_id AND t.transaction_type = 'DEPOSIT' AND t.reversed_flag = 'N'),0) as transaction_amount_sum, nvl((select nvl(sum(ccc.due_amount),0) - nvl(sum(ccc.received_amount),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item in (1,8,9,11,13)),0) as can_deduct_amount_sum, (nvl((select sum(t.transaction_amount) from csh_transaction t where t.contract_id = cc.contract_id AND t.transaction_type = 'DEPOSIT' AND t.reversed_flag = 'N'),0) - nvl((select nvl(sum(ccc.due_amount),0) - nvl(sum(ccc.received_amount),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item in (1,8,9,11,13)),0)) as can_return_amount_sum, (Select hm.bp_name From hls_bp_master hm Where hm.bp_id = cc.bp_id_vender) bp_id_vender_n, (select ccc.due_date from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.times = (select max(c.times) from con_contract_cashflow c where c.cf_item = 1 and c.contract_id = ccc.contract_id and rownum = 1) and rownum = 1) rent_due_date from con_contract cc where cc.contract_status='INCEPT' AND CC.document_type in('CONL','CONLB') --and cc.DEPOSIT_DEDUCTION='10' and exists (select 1 from csh_transaction t where t.contract_id = cc.contract_id AND t.transaction_type = 'DEPOSIT' AND t.reversed_flag = 'N') ) t1
AND t1.contract_number like #{depositContractNumber}
AND t1.contract_number like #{contractNumber}
and t1.deposit_contract_id = #{depositContractId}
and t1.tenant_id_n like #{tenantIdN}
and t1.manufacturer_id_n = #{manufacturerIdN}
and t1.factory_id_n = #{factoryIdN}
and t1.bp_id_vender_n = #{bpIdVenderN}
and t1.rent_due_date >= #{orderStartDate}
and t1.rent_due_date <= #{orderEndDate}
